INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (19, 15, 'theory', 'Quiz: block devices and filesystems');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 15, 0, 'Why is it better to write UUID=… in /etc/fstab than /dev/sdb1?', '["A UUID is read faster at boot", "The name sdb1 is forbidden in fstab", "sdX names follow detection order and may change; the UUID is stored on the disk", "A UUID is needed only for swap"]', 2, 'The kernel numbers disks in detection order, and after a reboot or an added disk sdb may become another device. The UUID is written in the filesystem itself and does not depend on order.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 15, 1, 'What is true of an MBR partition table with a 512-byte sector?', '["The limit is 2 TiB and four entries, one of which may be extended", "The limit is 8 ZiB and 128 entries", "The limit is 2 TiB, but any number of entries", "There is no limit, but a protective GPT is needed"]', 0, 'MBR sector addresses are 32-bit: 2^32 sectors of 512 bytes give 2 TiB. There are four primary entries; logical partitions live inside the extended one.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 15, 2, 'Which statement about resizing is correct?', '["XFS is shrunk with xfs_growfs and a negative size", "ext4 can be shrunk while mounted", "First shrink the partition, then the filesystem", "XFS can only grow, ext4 can also shrink, but only unmounted"]', 3, 'In ordinary use XFS cannot shrink; ext4 is shrunk unmounted after e2fsck. When shrinking, the filesystem goes first and the partition second — otherwise data gets cut off.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 15, 3, 'df shows 100% while du over the whole filesystem gives a small total. What is a likely cause?', '["A partition table error", "A deleted file that a process keeps open", "du uses too large a block size", "The noatime option is on"]', 1, 'The space of a deleted file is freed when every process has closed it. du does not see such a file, while df counts the used blocks. lsof +L1 helps find it.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 15, 4, 'fstab has an entry with a nonexistent UUID and no nofail. What happens at boot?', '["The entry is skipped silently", "The system deletes the entry from the file", "The system waits for the device (90 seconds by default) and drops into emergency mode", "The system mounts another disk of the same size"]', 2, 'A mount without nofail is required by local-fs.target, and its failure triggers emergency mode. With nofail the entry is merely wanted.');
